uv run nexuscli eval run --real --file examples/evals/suite; uv run python -c "import json,pathlib,collections; man=json.loads(pathlib.Path('examples/evals/suite/meta/manifest.json').read_text()); rep=json.loads(pathlib.Path('.nexuscli/evals/last-real-report.json').read_text()); obs={s['name']:s for s in rep['scenarios']}; filled=0; grid=collections.Counter(); ok=collections.Counter(); tot=collections.Counter();
for e in man['scenarios']:
    o=obs.get(e['id']); assert o, e['id']; e['calibration']={'status':o['status'],'tokens':o.get('cost',{}).get('total_usage',{}).get('total_tokens',0),'turns':max([r.get('turns',0) for r in o.get('runs',[])], default=0)}; filled+=1; k=(e['category'],e['difficulty']); grid[k]+=1; tot[k]+=1; ok[k]+= (o['status']=='pass')
pathlib.Path('examples/evals/suite/meta/manifest.json').write_text(json.dumps(man,ensure_ascii=False,indent=2)+'
'); assert filled==30, filled; print('CALIBRATED', filled, 'scenarios'); [print(k, f'{ok[k]}/{tot[k]}') for k in sorted(tot)]"

